package org.apache.commons.math.optimization.univariate;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.exception.NotStrictlyPositiveException;
import org.apache.commons.math.optimization.GoalType;
import org.apache.commons.math3.exception.MaxCountExceededException;
import org.apache.commons.math3.optimization.univariate.BrentOptimizer;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for BrentOptimizer constructor.
 * Since the constructor only sets internal state via setters, 
 * we test the default state by performing a simple optimization.
 */
public class BrentOptimizer_BrentOptimizer_TriageGen2Test {

    @Test
    public void testConstructorSetsDefaultValues() {
        // Since fields are private, we verify the constructor's effect 
        // by running a standard optimization that relies on these default settings.
        BrentOptimizer optimizer = new BrentOptimizer();

        // f(x) = (x - 2)^2. Minimum is at x = 2.
        UnivariateRealFunction function = x -> Math.pow(x - 2.0, 2);

        try {
            double result = optimizer.optimize(function, GoalType.MINIMIZE, 0.0, 5.0);

            // Verify the result is close to 2.0 within the precision set by the constructor
            // Absolute accuracy is 1E-10, Relative is 1.0e-14
            Assert.assertEquals(2.0, result, 1e-9);
        } catch (Exception e) {
            Assert.fail("Optimization failed with default constructor settings: " + e.getMessage());
        }
    }

    @Test
    public void testOptimizeWithStartValue() {
        BrentOptimizer optimizer = new BrentOptimizer();

        // f(x) = (x - 3)^2. Minimum is at x = 3.
        UnivariateRealFunction function = x -> Math.pow(x - 3.0, 2);

        try {
            // Using the signature: optimize(f, goalType, min, max, startValue)
            double result = optimizer.optimize(function, GoalType.MINIMIZE, 0.0, 10.0, 8.0);
            Assert.assertEquals(3.0, result, 1e-9);
        } catch (Exception e) {
            Assert.fail("Optimization with start value failed: " + e.getMessage());
        }
    }

    @Test
    public void testOptimizeMaximization() {
        BrentOptimizer optimizer = new BrentOptimizer();

        // f(x) = -(x - 1)^2. Maximum is at x = 1.
        UnivariateRealFunction function = x -> -Math.pow(x - 1.0, 2);

        try {
            double result = optimizer.optimize(function, GoalType.MAXIMIZE, 0.0, 5.0);
            Assert.assertEquals(1.0, result, 1e-9);
        } catch (Exception e) {
            Assert.fail("Maximization optimization failed: " + e.getMessage());
        }
    }

    @Test(expected = MaxCountExceededException.class)
    public void testMaxIterationsExceeded() {
        // To trigger MaxIterationsExceededException, we use a function that 
        // oscillates wildly or is difficult to converge, combined with 
        // a very low iteration limit if we could set it. 
        // Since we are testing the constructor, we rely on the default 100 iterations.

        BrentOptimizer optimizer = new BrentOptimizer();

        // A function that is extremely difficult to converge within 100 iterations
        // e.g., a very high frequency sine wave
        UnivariateRealFunction function = x -> Math.sin(1.0 / (x + 0.0000000001));

        // This might not always trigger depending on the math engine's luck, 
        // but it's the standard way to test the exception path.
        optimizer.optimize(function, GoalType.MINIMIZE, 0.1, 1.0);
    }
}
